"""Local ChromaDB retrieval using embeddings generated by a local Ollama model."""

from __future__ import annotations

import json
import logging
import os
import time
import urllib.error
import urllib.request
from pathlib import Path
from typing import Any, Callable, Sequence

import chromadb

logger = logging.getLogger(__name__)

ROOT = Path(__file__).resolve().parents[1]
DATASET_PATH = ROOT / "data" / "deployment_logs.json"
PERSIST_DIRECTORY = Path(os.getenv("CHROMA_PERSIST_DIRECTORY", ROOT / ".chroma"))
COLLECTION_NAME = "ai_log_assistant_deployment_knowledge"
GENERAL_SCOPE = "__general__"
OLLAMA_BASE_URL = os.getenv("OLLAMA_BASE_URL", "http://127.0.0.1:11434").rstrip("/")
EMBEDDING_MODEL = os.getenv("OLLAMA_EMBEDDING_MODEL", "nomic-embed-text")
EmbeddingProvider = Callable[[Sequence[str]], list[list[float]]]


class EmbeddingUnavailableError(RuntimeError):
    """Raised when the configured local embedding endpoint cannot be reached."""


def ollama_embeddings(texts: Sequence[str]) -> list[list[float]]:
    """Generate local embeddings with Ollama's /api/embed endpoint."""
    body = json.dumps({"model": EMBEDDING_MODEL, "input": list(texts)}).encode("utf-8")
    request = urllib.request.Request(
        f"{OLLAMA_BASE_URL}/api/embed",
        data=body,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as error:
        details = error.read().decode("utf-8", errors="replace").strip()
        reason = f" Ollama response: {details}" if details else ""
        raise EmbeddingUnavailableError(
            f"Ollama embedding request failed with HTTP {error.code}; "
            f"verify that model {EMBEDDING_MODEL!r} is available locally.{reason}"
        ) from error
    except urllib.error.URLError as error:
        raise EmbeddingUnavailableError(
            f"Local Ollama embedding service is not reachable at {OLLAMA_BASE_URL}."
        ) from error
    except (TimeoutError, json.JSONDecodeError) as error:
        raise EmbeddingUnavailableError("Ollama did not return a valid embedding response.") from error
    embeddings = payload.get("embeddings")
    if not isinstance(embeddings, list) or len(embeddings) != len(texts):
        raise EmbeddingUnavailableError("Ollama returned an unexpected embedding response.")
    return embeddings


def _client(persist_directory: str | Path | None = None) -> chromadb.ClientAPI:
    location = Path(persist_directory) if persist_directory is not None else PERSIST_DIRECTORY
    location.mkdir(parents=True, exist_ok=True)
    return chromadb.PersistentClient(path=str(location))


def _embedding_text(record: dict[str, Any]) -> str:
    return "\n".join(
        (
            "Domain: deployment and DevOps troubleshooting",
            f"Project: {record.get('project', 'unknown')}",
            f"Service: {record.get('service', 'unknown')}",
            f"Deployment stage: {record.get('deployment_stage', 'unknown')}",
            f"Log: {record.get('normalized_message', record.get('raw_log', ''))}",
            f"Raw log: {record.get('raw_log', '')}",
            f"Incident type: {record.get('incident_type', '')}",
            f"Probable root cause: {record.get('probable_root_cause', '')}",
            f"Troubleshooting steps: {'; '.join(record.get('troubleshooting_steps', []))}",
            f"Expected resolution: {record.get('expected_resolution', '')}",
        )
    )


def _retrieval_text(new_log: str, deployment_stage: str | None = None) -> str:
    abbreviations = {
        "DB": "database",
        "CONN": "connection",
        "AUTH": "authentication",
        "SVC": "service",
        "REQ": "request",
        "RESP": "response",
    }
    expanded = " ".join(
        abbreviations.get(token.upper(), token)
        for token in new_log.replace("_", " ").split()
    )
    lower_log = new_log.lower()
    troubleshooting_terms: list[str] = []
    if "connection refused" in lower_log:
        troubleshooting_terms.extend(
            ("TCP connection", "network connectivity", "endpoint listener", "port")
        )
    if "crashloopbackoff" in lower_log or "readiness probe" in lower_log:
        troubleshooting_terms.extend(
            ("Kubernetes pod restart", "container startup", "health check")
        )
    if "imagepullbackoff" in lower_log:
        troubleshooting_terms.extend(("Kubernetes image pull", "registry", "image credentials"))
    if "oomkilled" in lower_log or "out of memory" in lower_log:
        troubleshooting_terms.extend(("container memory limit", "resource exhaustion"))
    stage = f"Deployment stage: {deployment_stage}\n" if deployment_stage else ""
    concepts = (
        f"\nTroubleshooting concepts: {'; '.join(troubleshooting_terms)}"
        if troubleshooting_terms
        else ""
    )
    return f"Deployment troubleshooting log:\n{stage}{new_log}\n{expanded}{concepts}"


def _metadata(record: dict[str, Any]) -> dict[str, str]:
    record_metadata = record.get("metadata", {})
    company = record.get("company") or (
        record_metadata.get("company") if isinstance(record_metadata, dict) else None
    )
    return {
        "project": str(record.get("project", "unknown")),
        "service": str(record.get("service", "unknown")),
        "deployment_stage": str(record.get("deployment_stage", "unknown")),
        "incident_type": str(record.get("incident_type", "unknown")),
        "severity": str(record.get("severity", "unknown")),
        "company_scope": str(company or GENERAL_SCOPE),
    }


def ingest_dataset(
    dataset_path: str | Path = DATASET_PATH,
    *,
    persist_directory: str | Path | None = None,
    collection_name: str = COLLECTION_NAME,
    embedding_provider: EmbeddingProvider = ollama_embeddings,
    client: chromadb.ClientAPI | None = None,
    batch_size: int = 64,
) -> int:
    """Upsert the deployment troubleshooting dataset into a persistent collection.

    Dataset records without a company field are explicitly marked as generalized
    knowledge. Company-specific records can be added using the same JSON schema
    plus a ``company`` field; their scope is isolated during retrieval.
    """
    path = Path(dataset_path)
    records = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(records, list):
        raise ValueError(f"Dataset must be a JSON array: {path}")
    if not records:
        return 0
    chroma = client or _client(persist_directory)
    collection = chroma.get_or_create_collection(
        name=collection_name,
        metadata={"hnsw:space": "cosine"},
    )
    for offset in range(0, len(records), batch_size):
        batch = records[offset : offset + batch_size]
        embeddings = embedding_provider([_embedding_text(record) for record in batch])
        if len(embeddings) != len(batch):
            raise ValueError("Embedding provider returned a different number of vectors than inputs.")
        collection.upsert(
            ids=[f"{_metadata(record)['company_scope']}:{record['id']}" for record in batch],
            embeddings=embeddings,
            documents=[json.dumps(record, ensure_ascii=False) for record in batch],
            metadatas=[_metadata(record) for record in batch],
        )
    return len(records)


def retrieve_context(
    company: str | None,
    project: str | None,
    service: str | None,
    new_log: str,
    *,
    deployment_stage: str | None = None,
    n_results: int = 4,
    collection_name: str = COLLECTION_NAME,
    persist_directory: str | Path | None = None,
    embedding_provider: EmbeddingProvider = ollama_embeddings,
    client: chromadb.ClientAPI | None = None,
) -> list[dict[str, Any]]:
    """Retrieve scoped company knowledge first, then generalized examples.

    Another company's records are never queried. General knowledge is explicitly
    marked in each returned result and may fill slots after company-specific hits.
    """
    if n_results < 1:
        raise ValueError("n_results must be at least 1.")
    retrieval_started = time.perf_counter()
    chroma = client or _client(persist_directory)
    collection = chroma.get_or_create_collection(
        name=collection_name,
        metadata={"hnsw:space": "cosine"},
    )
    if collection.count() == 0:
        logger.info(
            "rag_timing embedding_ms=0.0 query_ms=0.0 total_ms=%.1f "
            "candidate_count=0 returned_count=0",
            (time.perf_counter() - retrieval_started) * 1000,
        )
        return []
    company_value = (company or "").strip()
    project_value = (project or "").strip()
    service_value = (service or "").strip()
    embedding_started = time.perf_counter()
    query_embedding = embedding_provider([_retrieval_text(new_log, deployment_stage)])
    embedding_ms = (time.perf_counter() - embedding_started) * 1000
    if len(query_embedding) != 1:
        raise ValueError("Embedding provider must return exactly one vector for a query.")

    def search(
        where: dict[str, Any],
        limit: int,
        *,
        scope_label: str,
        context_match: str,
    ) -> list[dict[str, Any]]:
        if limit <= 0:
            return []
        result = collection.query(
            query_embeddings=query_embedding,
            n_results=limit,
            where=where,
            include=["documents", "metadatas", "distances"],
        )
        documents = result.get("documents", [[]])[0]
        metadatas = result.get("metadatas", [[]])[0]
        distances = result.get("distances", [[]])[0]
        items: list[dict[str, Any]] = []
        for document, metadata, distance in zip(documents, metadatas, distances):
            record = json.loads(document)
            record["_retrieval"] = {
                "scope": scope_label,
                "context_match": context_match,
                "deployment_stage": metadata.get("deployment_stage", "unknown"),
                "distance": distance,
            }
            items.append(record)
        return items

    general_scope = {"company_scope": GENERAL_SCOPE}
    project_limit = max(n_results * 16, 60)
    candidates: list[dict[str, Any]] = []
    query_started = time.perf_counter()
    if company_value:
        company_where: dict[str, Any] = {
            "$and": [{"company_scope": company_value}, {"project": project_value}]
        }
        candidates.extend(
            search(
                company_where,
                project_limit,
                scope_label="company",
                context_match="project",
            )
        )
    if project_value:
        general_project_where: dict[str, Any] = {
            "$and": [general_scope, {"project": project_value}]
        }
        candidates.extend(
            search(
                general_project_where,
                project_limit,
                scope_label="general",
                context_match="project",
            )
        )
    if not candidates:
        candidates.extend(
            search(
                general_scope,
                n_results,
                scope_label="general",
                context_match="global",
            )
        )
    query_ms = (time.perf_counter() - query_started) * 1000

    deduplicated: dict[str, dict[str, Any]] = {}
    for record in candidates:
        record_id = str(record.get("id", ""))
        current = deduplicated.get(record_id)
        if current is None or (
            record["_retrieval"]["scope"] == "company"
            and current["_retrieval"]["scope"] != "company"
        ):
            deduplicated[record_id] = record

    def rank(record: dict[str, Any]) -> tuple[float, str]:
        details = record["_retrieval"]
        contextual_distance = float(details["distance"])
        if details["scope"] == "company":
            contextual_distance -= 0.2
        if record.get("service") == service_value:
            contextual_distance -= 0.06
            details["context_match"] = "service"
        return contextual_distance, str(record.get("id", ""))

    results = sorted(deduplicated.values(), key=rank)[:n_results]
    logger.info(
        "rag_timing embedding_ms=%.1f query_ms=%.1f total_ms=%.1f "
        "candidate_count=%d returned_count=%d",
        embedding_ms,
        query_ms,
        (time.perf_counter() - retrieval_started) * 1000,
        len(deduplicated),
        len(results),
    )
    return results
